import unittest
from subject import route


class RouteTest(unittest.TestCase):
    # 判準來源：題目規格與已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_all_days_0_to_4(self):
        # 可抓：weekday/weekend 邊界錯在 4 附近（如 day>=4）
        for d in range(0, 5):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_days_5_and_6(self):
        # 可抓：邊界錯成 day>=6 或 day==5
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_every_valid_day(self):
        # 可抓：略過 enabled 檢查、只在部分日子 paused
        for d in range(0, 7):
            self.assertEqual(route(d, False), "paused", d)

    def test_invalid_day_out_of_range(self):
        # 可抓：範圍邊界寫成 <=-1 漏掉、或 >7 漏掉 7
        for d in (-1, 7, 100):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

    def test_invalid_day_non_int_string(self):
        # 可抓：缺少型別檢查；且驗證 day 先於 enabled（enabled=False 仍要拒絕）
        for d in ("3", "abc", ""):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

